const http = require('node:http');
const https = require('node:https');
const fetch = globalThis.fetch || ((urlString, options = {}) => new Promise((resolve, reject) => {
  const transport = String(urlString).startsWith('https://') ? https : http;
  const req = transport.request(urlString, {
    method: options.method || 'GET',
    headers: options.headers || {},
  }, (res) => {
    let body = '';
    res.on('data', (chunk) => {
      body += chunk.toString();
    });
    res.on('end', () => {
      resolve({
        ok: (res.statusCode || 0) >= 200 && (res.statusCode || 0) < 300,
        status: res.statusCode || 0,
        text: async () => body,
        json: async () => body ? JSON.parse(body) : {},
      });
    });
  });
  req.on('error', reject);
  if (options.body) {
    req.write(options.body);
  }
  req.end();
}));

const runnerBase = $env.AUTOMATION_RUNNER_BASE_URL;
const runnerToken = $env.AUTOMATION_RUNNER_TOKEN;
if (!runnerBase) throw new Error('AUTOMATION_RUNNER_BASE_URL is not configured');

const response = $input.first().json;
const workItems = Array.isArray(response.results) ? response.results : [];

const qualityFindings = workItems
  .map((item) => {
    const description = (item.description_stripped ?? '').replace(/\s+/g, ' ').trim();
    const hasAcceptance = /Acceptance Criteria/i.test(description);
    const hasRepoMetadata = /Repo Metadata/i.test(description);
    const shallowDescription = description.length < 180;
    const missingOutcomeNote = item.completed_at && !/Outcome|Completed|Decision|Follow-up/i.test(description);

    const reasons = [];
    if (shallowDescription) reasons.push('description is too shallow');
    if (!hasAcceptance) reasons.push('missing acceptance criteria section');
    if (!hasRepoMetadata) reasons.push('missing repo metadata section');
    if (missingOutcomeNote) reasons.push('completed item lacks explicit outcome note');

    if (reasons.length === 0) return null;

    return {
      id: item.id,
      title: item.name,
      priority: item.priority ?? 'none',
      updatedAt: item.updated_at,
      reasons,
    };
  })
  .filter(Boolean);

const summaryLines = qualityFindings.length === 0
  ? ['No backlog quality issues found.']
  : qualityFindings.map((finding, index) => `${index + 1}. ${finding.title} -> ${finding.reasons.join('; ')}`);

const dateStamp = new Date().toISOString().slice(0, 10);
const reportRelativePath = `backlog-audits/${dateStamp}.md`;
const reportContent = [
  '# Plane Backlog Quality Audit',
  '',
  `Generated: ${new Date().toISOString()}`,
  `Findings: ${qualityFindings.length}`,
  '',
  '## Summary',
  '',
  ...summaryLines,
].join('\n');

const writeResponse = await fetch(`${runnerBase}/reports/write`, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    ...(runnerToken ? { Authorization: `Bearer ${runnerToken}` } : {}),
  },
  body: JSON.stringify({
    relativePath: reportRelativePath,
    content: reportContent,
  }),
});

if (!writeResponse.ok) {
  const body = await writeResponse.text();
  throw new Error(`Runner report write failed: ${writeResponse.status} ${body}`);
}

return [{
  json: {
    generatedAt: new Date().toISOString(),
    findingCount: qualityFindings.length,
    findings: qualityFindings,
    summary: summaryLines.join('\n'),
    reportRelativePath,
  },
}];
